	var output []byte
	output, _, err = evm.Call(vm.AccountRef(c.caller), c.to, input, math.MaxUint64, big.NewInt(0))
	if err != nil {
		return *new(common.Hash), err
	}
	out, err := c.abi.Unpack("getNonce", output)
	if err != nil {
		return *new(common.Hash), err
	}

	out0 := *abi.ConvertType(out[0], new(common.Hash)).(*common.Hash)

	return out0, err
